export function clearAnonCookie(res: Response): void {
  const { maxAge: _maxAge, ...rest } = anonCookieOptions();
  res.clearCookie(ANON_COOKIE_NAME, rest);
}

/**
 * Zwraca UUID kandydata z zweryfikowanego ciasteczka albo undefined. Nigdy nie rzuca —
 * brak ciasteczka i ciasteczko podrobione są dla wołającego tym samym przypadkiem.
 */
export function readAnonCandidateUuid(req: Request): string | undefined {
  const cookies = (req as Request & { cookies?: Record<string, string> }).cookies;
  const token = cookies?.[ANON_COOKIE_NAME];
  if (!token) return undefined;
  try {
    const payload = jwt.verify(token, secretOrThrow()) as Partial<AnonPayload>;
    if (payload.typ !== "anon" || typeof payload.cuid !== "string") return undefined;
    return payload.cuid;
  } catch {
    return undefined;
  }
}

