 * z sekretu serwera, więc skrótów nie da się porównać z niczym spoza tej instalacji.
 */
export function hashClientIp(req: Request): string {
  const ip = req.ip ?? "nieznany";
  return createHmac("sha256", `${secretOrThrow()}|anon-ip`).update(ip).digest("hex");
}
