namespace McpFilesystemHttp {
  export type EditFileInput = {
    /**
     * Path to the file
     */
    path: string;
    /**
     * Exact text to find
     */
    find: string;
    /**
     * Text to replace it with
     */
    replace: string;
    /**
     * Replace all occurrences (default true)
     */
    all?: boolean | undefined;
  };

  /**
   * Replace an exact text sequence in a file with new content. Returns the number of replacements made.
   */
  export async function editFile(input: EditFileInput): Promise<any>
}

